function numberOfUniqueGoodSubsequences(binary) {
  const n = binary.length;
  const seen = new Set();
  for (let mask = 1; mask < (1 << n); mask++) {
    let text = '';
    for (let i = 0; i < n; i++) if (mask & (1 << i)) text += binary[i];
    if (text === '0' || text[0] === '1') seen.add(text);
  }
  return seen.size;
}

