function generate(rand, size) {
  const n = size === 'large' ? 5000 + Math.floor(rand() * 5001) : 1 + Math.floor(rand() * 12);
  const ones = [0.5, 0.1, 0.9, 1, 0][Math.floor(rand() * 5)];
  let binary = '';
  for (let i = 0; i < n; i++) binary += rand() < ones ? '1' : '0';
  return [binary];
}
